contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 preset, uint256 val) public payable {
        // Preset the value using the first accepted mechanism: SetMinSum(preset).
        // preset can be any uint, including 0.
        uint256 minBefore;
        bool firstReverted;
        c.SetMinSum(preset); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }
        minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        // Now drive the public entry SetMinSum(val).
        bool reverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted = true; } else { reverted = false; }
        uint256 minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        // General rule: MinSum is never decreased by a failed call, and after the
        // second call the value can only be the newly supplied val or the pre-call
        // value. Additionally, if the first call succeeded and set a non-zero value,
        // the second call must revert and leave MinSum unchanged.
        assert(
            (reverted && minAfter == minBefore) ||
            (!reverted && minAfter == val) ||
            (!firstReverted && preset != 0 && reverted && minAfter == preset)
        );
    }

    receive() external payable {}
}

