pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 preset, uint256 val) internal {
        uint256 minBefore;
        bool firstReverted;
        try c.SetMinSum(preset) { firstReverted = false; } catch { firstReverted = true; }
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(val) { reverted = false; } catch { reverted = true; }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        assertTrue((reverted && minAfter == minBefore) ||
            (!reverted && minAfter == val) ||
            (!firstReverted && preset != 0 && reverted && minAfter == preset));
    }

    function testFuzz_run(uint256 preset, uint256 val) public {
        _run(preset, val);
    }

    receive() external payable {}
}
